import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"27、【颐】 震下艮上","description":"周易集注 - 27、【颐】 震下艮上","frontmatter":{"title":"27、【颐】 震下艮上","description":"周易集注 - 27、【颐】 震下艮上"},"headers":[],"relativePath":"zh/classics/jizhu/031.md","filePath":"zh/classics/jizhu/031.md"}'),h={name:"zh/classics/jizhu/031.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_27、【颐】-震下艮上" tabindex="-1">27、【颐】 震下艮上 <a class="header-anchor" href="#_27、【颐】-震下艮上" aria-label="Permalink to “27、【颐】 震下艮上”">​</a></h1><p>颐，口旁也。食物以自养，故取养义。为卦上下二阳，内含四阴，外实内虚，上止下动，故名为颐。《序卦》“物畜然后可养，故受之以颐”，所以次大畜。</p><p>夲卦大象离目，观之象也。阳实阴虚，实者养人，虚者求人之养，自求口实者。自求养于阳之实也。震不求艮，艮不求震，惟自求同体之阳，故曰自求。爻辞见之。</p><p>《彖》曰：颐，贞吉，养正则吉也。观颐，观其所养也。自求口实，观其自养也。天地养万物，圣人养贤以及万民，颐之时大矣哉。</p><p>释卦辞。极言养道而赞之。观其所养者，观其所以养人之道正不正也，指上下二阳也。观其自养者，观其求口实以自养之正不正也，指中间四阴也。本卦颐，原从口无养德之意，惟颐养得正，则养德即在其中矣。不但养人自养，以至天地圣人养万物，养万民，无非养之所在，故曰颐之时大矣哉。与大过解革同。</p><h3 id="《象》曰-山下有雷-颐-君子以慎言语-节饮食。" tabindex="-1">《象》曰：山下有雷，颐，君子以慎言语，节饮食。 <a class="header-anchor" href="#《象》曰-山下有雷-颐-君子以慎言语-节饮食。" aria-label="Permalink to “《象》曰：山下有雷，颐，君子以慎言语，节饮食。”">​</a></h3><p>帝出乎震，万物得养而生成。言乎艮，万物得养而成。君子慎言语以养其德，节饮食以养其体，言语饮食动之象慎也。节也，止之象。此处方说出养德。</p><p>初九，舍尔灵龟，观我朵颐，凶。舍，音舍</p><p>大象离，龟之象也。应爻艮止中空，灵龟止而不食，服气空腹之象也。朵者，垂朵也。震反生，朵之象也。垂下其颐以垂涎，乃欲食之貌也。尔者，四也。我者，初也。灵龟以静止为养，朵颐以震动为养，故尔四而我初。大象离目，又观之象也。</p><p>初九阳刚乃养人者也，但其位卑下，不能养人及民，又乃动体，当颐养之初，正上止下动之时。惟知有口体之欲，舍六四而不养，故有舍尔灵龟，观我朵颐之象。饮食，人贱凶之道也，故其占如此。</p><h3 id="《象》曰-观我朵颐-亦不足贵也。" tabindex="-1">《象》曰：观我朵颐，亦不足贵也。 <a class="header-anchor" href="#《象》曰-观我朵颐-亦不足贵也。" aria-label="Permalink to “《象》曰：观我朵颐，亦不足贵也。”">​</a></h3><p>饮食之人，则人贱之，故不足贵。</p><p>六二，颠颐，拂经，于丘颐，征凶。</p><p>颠者，顶也。指外卦也。拂者，除也，去也，违悖之意。诸爻皆求养于统体之阳，不从应与，故有颠拂之象。颠颐者，求养于上也。拂经者，违悖养于同体之常经也。山阜曰：丘土之高者，艮之象也。于丘颐者，求养于外，即颠颐也。凶者，求食于权门，必见拒而取羞也。</p><p>六二阴柔，不能自养，必待养于阳刚。然震性妄动，不求养于初，而求养于外，则违养道之常理而行失其类矣。故教占者，当求养于初。若于丘颐，不惟不得其养，而往则凶也。故其象占如此。</p><h3 id="《象》曰-六二征凶-行失类也。" tabindex="-1">《象》曰：六二征凶，行失类也。 <a class="header-anchor" href="#《象》曰-六二征凶-行失类也。" aria-label="Permalink to “《象》曰：六二征凶，行失类也。”">​</a></h3><p>养道各从其类，二三养于初，四五养于上，今二颠颐，往失其类矣，故曰失类。曰行者，震足之象也。</p><p>六三，拂颐，贞凶。十年勿用，无攸利。</p><p>拂颐者，违拂所养之道，不求养于初，而求养于上之正应也。贞者，正也。上乃正应，亦非不正也。十年者，中爻坤，土之成数也。勿用者，不得用其养也。口容止所以下三爻养于动者，皆凶。上三爻养于止者，皆吉。</p><p>六三阴柔，不中正，本乃动体，至三则动极而妄动矣，故有拂颐之象。占者得此，虽正亦凶。至于十年之久。理极数穷，亦不可往，其凶至此。</p><h3 id="《象》曰-十年勿用-道大悖也。" tabindex="-1">《象》曰：十年勿用，道大悖也。 <a class="header-anchor" href="#《象》曰-十年勿用-道大悖也。" aria-label="Permalink to “《象》曰：十年勿用，道大悖也。”">​</a></h3><p>震为大涂，道之象也，大悖，即拂颐。</p><p>六四，颠颐，吉，虎视眈眈，其欲逐逐，无咎。耽，都含切</p><p>颠者，顶也，与六二同。颠颐者，求养于上也。吉者，得养道之常经也。艮为虎，虎之象也。天下之物，自养于内者莫如龟，求养于外者莫如虎。龟自养于内，内卦初舍之，故凶。虎求养于外，外卦上施之，故吉。爻辞之精至此。耽者，视近而志远也。变离目，视之象也。应爻初为地位，虎行垂首下视于地，视近也。而心志乃求养于天位之上，志远也，故以耽字言之。视下卦，耽也。志上卦，耽也。故曰耽耽。阴者，人欲之象也。下卦二阴欲也。上卦二阴，欲也。人欲重叠追逐而来，故曰逐逐。耽者，四求养于上也。逐者，上施养于四也。</p><p>六四当颐养之时，求养于上，故有颠颐之象，吉之道也。故占者吉。然四求养于上，上施养于四。四得所养矣，故又有视耽欲逐之象。以求养而得逐逐之欲，似有过咎矣。然养得其正，故占者不惟吉，而又无咎也。</p><h3 id="《象》曰-颠颐之吉-上施光也。施去声" tabindex="-1">《象》曰：颠颐之吉，上施光也。施去声 <a class="header-anchor" href="#《象》曰-颠颐之吉-上施光也。施去声" aria-label="Permalink to “《象》曰：颠颐之吉，上施光也。施去声”">​</a></h3><p>施者及也。布散惠与之义，详见乾卦“云行雨施”，言上养及于四也。光者，艮笃实，光辉其道，光明也。变离日，亦光之象也。</p><p>六五，拂经，居贞吉，不可涉大川。</p><p>拂经者，五与内卦为正应，亦如二之求养于上，违悖养于同体之常道也。故二五皆言拂经，居者静以守之也，贞者求养于同体之阳，乃任贤养民之正道也。吉者，恩不自出而又能养人也。不可涉大川者，言不可自用以济人也。涉川必乾刚，五柔故不可涉。</p><p>六五居尊，能自养人者也。但阴柔不正，无养人之才，又与内卦为正应，亦有拂经之象。然养贤及民，君道之正，故教占者顺以从上，守此正道则吉，不可不量己之力而当济人之任也。</p><h3 id="《象》曰-居贞之吉-顺以从上也。" tabindex="-1">《象》曰：居贞之吉，顺以从上也。 <a class="header-anchor" href="#《象》曰-居贞之吉-顺以从上也。" aria-label="Permalink to “《象》曰：居贞之吉，顺以从上也。”">​</a></h3><p>中爻坤顺，故曰顺。言顺从上而养人也。</p><p>上九，由颐，厉，吉，利涉大川。</p><p>由者从也。九以阳刚居上位，是天下之养皆从上九以养之也。厉者，上而知君赖我以养也，则恐专权僭逼，而此心无一事之或忽。下而知民由我以养也，则常握发吐哺而此心无一时之或宁。此上九之所谓厉也。故戒之以厉，而后许之以吉也。凡易言涉大川，取干者，以卦德也。以干天下至健，德行恒易，以知险也。需、同人、大畜是也。取水木者，以卦体也。涣、蛊、未济、谦，或取中爻，或取卦变是也。取中虚者，以卦象也。益、中孚、颐是也。五不可涉大川，上九利涉大川，方见五赖上九以养人。</p><p>上九以阳刚之德居尊位，六五赖其贤以养人，故有由颐之象。然位高任重，必厉而后吉，即天下有险阻亦可以济之而不失其养也。其占又如此。</p><h3 id="《象》曰-由颐厉吉-大有庆也。" tabindex="-1">《象》曰：由颐厉吉，大有庆也。 <a class="header-anchor" href="#《象》曰-由颐厉吉-大有庆也。" aria-label="Permalink to “《象》曰：由颐厉吉，大有庆也。”">​</a></h3><p>得所养下之庆，亦君上之庆，故大。</p>',37)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
